<script setup>import BaseModal from './BaseModal.vue'; import BaseButton from './BaseButton.vue'; defineProps({ open: Boolean, title: String, message: String, confirmLabel: { type: String, default: 'Konfirmasi' }, cancelLabel: { type: String, default: 'Kembali' }, danger: Boolean, loading: Boolean }); const emit = defineEmits(['confirm', 'cancel']);</script>
<template><BaseModal :open="open" :title="title" size="sm" @close="emit('cancel')"><p class="text-sm text-[#667085]">{{ message }}</p><template #footer><BaseButton variant="secondary" @click="emit('cancel')">{{ cancelLabel }}</BaseButton><BaseButton :variant="danger ? 'danger' : 'primary'" :loading="loading" @click="emit('confirm')">{{ confirmLabel }}</BaseButton></template></BaseModal></template>
